      "solutionDesc": "Create a private photo event before the party starts. Share the QR code at the door or in the group chat. Guests upload photos all night long. You wake up to a complete gallery — no chasing, no begging, no FOMO.",
      "howItWorksTitle": "Three steps to the perfect party gallery",
      "step1Title": "Create your event",
      "step1Desc": "Name it after your party. Takes 10 seconds. No account needed to start.",
      "step2Title": "Share the link or QR",
      "step2Desc": "Drop it in the group chat, print a card for the bar, or display it on a screen.",
      "step3Title": "Watch it fill up",
      "step3Desc": "Guests upload photos in real time. You get the full story of the night, instantly.",
      "featuresLabel": "Built for any gathering",
      "featuresTitle": "Why parties love SnapRooms",
      "feature1Title": "Works at any venue",
      "feature1Desc": "House party, rooftop bar, beach bonfire, or dinner club. The QR code works anywhere.",
      "feature2Title": "Real-time uploads",
      "feature2Desc": "Guests add photos while the night is still happening. The energy builds the gallery.",
      "feature3Title": "Invite-only access",
      "feature3Desc": "Only people with the link see the photos. What happens at the party stays at the party.",
      "feature4Title": "Zero friction",
      "feature4Desc": "No apps to download, no accounts to create. Open, upload, done.",
      "feature5Title": "No social media noise",
      "feature5Desc": "Keep the photos private. No public hashtags, no unwanted tagging, no drama.",
      "feature6Title": "Download the night",
      "feature6Desc": "Save every photo in original resolution on premium plans or unlocked events. Standard-quality downloads are always free.",
      "qrBadge": "QR Code Sharing",
      "qrTitle": "One QR code. Every guest. All the photos.",
      "qrDesc1": "Print a card for the entry table, add it to your digital invite, or flash it on the TV screen. Guests scan and upload in under 10 seconds.",
      "qrDesc2": "Works on every phone — even that one friend who still has an older model. No app store. No updates. Just scan and go.",
      "qrCardLabel": "Scan to add your photos",
      "qrCardSublabel": "No app needed",
      "privacyTitle": "What happens at the party stays private",
      "privacyDesc": "No public feeds. No data mining. No surprise tag notifications. Your party photos are yours and your guests' — nothing more.",
      "privacyFeature1Title": "Encrypted storage",
      "privacyFeature1Desc": "Your photos are stored securely and never sold to third parties.",
      "privacyFeature2Title": "You control access",
      "privacyFeature2Desc": "Only people with your event link can view or upload photos.",
      "privacyFeature3Title": "Download or delete",
      "privacyFeature3Desc": "Keep your gallery as long as you want or wipe it completely. Your choice.",
      "faqTitle": "Frequently asked questions",
      "faq1Question": "Do guests need to sign up or install anything?",
      "faq1Answer": "No. Guests open the QR code or link in their browser and upload photos directly from their camera roll. No apps, no accounts, no hassle.",
      "faq2Question": "Can I use this for a dinner party or small gathering?",
      "faq2Answer": "Absolutely. SnapRooms works for any size gathering — from intimate dinners to full-blown ragers. One event, any crowd.",
      "faq3Question": "Is there a photo limit?",
      "faq3Answer": "No. Guests can upload unlimited photos. There are no storage caps on free or Pro plans.",
      "faq4Question": "How private is the gallery?",
      "faq4Answer": "Completely private. Only people with your unique event link can access it. The gallery is not indexed by search engines and never appears on public feeds.",
      "faq5Question": "How long does the gallery stay open?",
      "faq5Answer": "Free galleries stay active for 7 days. Upgrade to Pro for permanent galleries that never expire.",
      "faq6Question": "Is it really free?",
      "faq6Answer": "Yes. Create one event, invite unlimited guests, and collect unlimited photos at no cost. Pro plans add unlimited events and permanent storage.",
      "finalTitle": "Never lose a party photo again",
      "finalDesc": "Create your party event in seconds and collect every moment from the night — before the memories fade.",
      "finalCta": "Create free party event",
      "finalMicrocopy": "Takes 10 seconds. No credit card required.",
      "emailPlaceholder": "Your email",
      "creating": "Creating...",
      "howItWorksLabel": "How it works",
      "viewPricing": "View pricing",
      "crossLabel": "More ways to use SnapRooms",
      "crossTitle": "Not just for private parties",
      "crossBirthdayQ": "Celebrating a birthday instead?",
      "crossBirthdayDesc": "Every candle, every laugh — one shared gallery for the whole celebration.",
      "crossBirthdayCta": "Birthdays",
      "crossWeddingQ": "Planning a wedding instead?",
      "crossWeddingDesc": "Collect every guest photo from the ceremony to the last dance.",
      "crossWeddingCta": "Weddings"
