      "faq2Question": "Kann ich das für ein Dinner oder eine kleine Zusammenkunft nutzen?",
      "faq2Answer": "Absolut. SnapRooms funktioniert für jede Gruppengröße — von intimen Dinners bis zu ausgelassenen Partys. Ein Event, jede Menge.",
      "faq3Question": "Gibt es ein Foto-Limit?",
      "faq3Answer": "Nein. Gäste können unbegrenzt Fotos hochladen. Es gibt keine Speicherlimits auf Free- oder Pro-Plänen.",
      "faq4Question": "Wie privat ist die Galerie?",
      "faq4Answer": "Komplett privat. Nur Leute mit deinem einzigartigen Event-Link können darauf zugreifen. Die Galerie wird nicht von Suchmaschinen indexiert und erscheint nie auf öffentlichen Feeds.",
      "faq5Question": "Wie lange bleibt die Galerie geöffnet?",
      "faq5Answer": "Free-Galerien bleiben 7 Tage aktiv. Upgrade auf Pro für permanente Galerien, die nie ablaufen.",
      "faq6Question": "Ist es wirklich kostenlos?",
      "faq6Answer": "Ja. Erstelle ein Event, lade unbegrenzte Gäste ein und sammle unbegrenzt Fotos ohne Kosten. Pro-Pläne fügen unbegrenzte Events und permanenten Speicher hinzu.",
      "finalTitle": "Verliere nie wieder ein Party-Foto",
      "finalDesc": "Erstelle dein Party-Event in Sekunden und sammle jeden Moment der Nacht — bevor die Erinnerungen verblassen.",
      "finalCta": "Kostenloses Party-Event erstellen",
      "finalMicrocopy": "Dauert 10 Sekunden. Keine Kreditkarte nötig.",
