      "privacyDisclaimer": "Diese Datenschutzerklärung ist ein produktbereiter Entwurf, der regeln soll, wie SnapRooms mit deinen Daten umgeht. Sie wird wie besehen bereitgestellt und stellt keine Rechtsberatung dar.",
      "termsDisclaimer": "Diese Nutzungsbedingungen sind ein produktbereiter Entwurf, der die Nutzung der SnapRooms-Plattform regeln soll. Sie werden wie besehen bereitgestellt und stellen keine Rechtsberatung dar. Wir empfehlen, einen qualifizierten Anwalt zu konsultieren, bevor du dich auf sie für Durchsetzung oder Compliance verlässt.",
