      "howStoreData": "Wie wir deine Daten speichern",
      "howStoreDesc1": "Datenbank: Event- und Besitzerdaten werden in PostgreSQL (Neon) gespeichert.",
      "howStoreDesc2": "Dateispeicher: Fotos werden in sicherem Blob-Speicher gespeichert.",
      "howStoreDesc3": "Passwörter: Besitzerpasswörter werden mit Salt gehasht — wir speichern nie Klartextpasswörter.",
