      "retentionDesc2": "Events und Fotos: Je nach Tarif (Free: 90 Tage; Pro Event: 12 Monate; Wedding Pro: 24 Monate; Professional: solange aktiv + 90 Tage Kulanz nach Kündigung). SnapRooms Vault verlängert die Dauer bei aktivem Abo.",
      "retentionDesc3": "Fotos: Automatisch gelöscht, wenn das zugehörige Event gelöscht wird.",
