      "requestDeletion": "Wie man eine Löschung beantragt",
      "requestDeletionDesc": "Du kannst ein Event und seine Fotos jederzeit von deinem Dashboard löschen. Wenn du möchtest, dass wir alle mit deiner E-Mail-Adresse verknüpften Daten löschen, kontaktiere uns unter",
