      "acceptanceOfTerms": "Accettazione dei Termini",
      "acceptanceDesc1": "Accedendo o utilizzando SnapRooms (\"il Servizio\"), accetti di essere vincolato da questi Termini di Servizio. Se non accetti questi termini, non puoi utilizzare il Servizio. Questi termini si applicano a tutti i visitatori, utenti, host di eventi e altri che accedono o utilizzano il Servizio.",
      "acceptanceDesc2": "Possiamo aggiornare questi termini di volta in volta. L'uso continuato del Servizio dopo le modifiche costituisce accettazione dei termini revisionati. Le modifiche sostanziali saranno comunicate via email o tramite un avviso prominente sulla piattaforma.",
      "serviceDescription": "Descrizione del Servizio",
      "serviceDesc1": "SnapRooms è una piattaforma web che consente agli host di eventi di creare eventi foto privati, generare codici QR e link condivisibili, e raccogliere foto dagli ospiti. Gli ospiti possono caricare foto senza creare un account. Il Servizio include strumenti per la moderazione delle foto, la gestione della galleria e il download in blocco.",
      "serviceDesc2": "Non garantiamo l'accesso ininterrotto al Servizio. Manutenzione, aggiornamenti o circostanze al di fuori del nostro controllo possono causare tempi di inattività temporanei. Ci riserviamo il diritto di modificare, sospendere o interrompere qualsiasi parte del Servizio in qualsiasi momento.",
      "userAccounts": "Account Utente",
      "userAccountsDesc1": "Per creare e gestire eventi foto, devi fornire un indirizzo email valido. Sei responsabile del mantenimento della riservatezza delle credenziali del tuo account e di tutte le attività che avvengono sotto il tuo account. Devi informarci immediatamente di qualsiasi uso non autorizzato.",
