      "contentPhotos": "Contenuti & Foto",
      "contentDesc1": "Mantieni la proprietà di tutte le foto e i contenuti che tu o i tuoi ospiti caricate su SnapRooms. Caricando contenuti, ci concedi una licenza limitata, non esclusiva, senza royalties per archiviare, visualizzare e trasmettere tali contenuti esclusivamente ai fini del funzionamento del Servizio.",
      "contentDesc2": "Non rivendichiamo la proprietà dei tuoi contenuti. Non vendiamo le tue foto né le utilizziamo per pubblicità senza il tuo esplicito consenso. Sei responsabile di assicurarti di avere il diritto di condividere qualsiasi contenuto caricato nei tuoi eventi.",
      "contentDesc3": "Ci riserviamo il diritto di rimuovere contenuti che violano questi termini o che riteniamo ragionevolmente illegali, senza preavviso.",
      "contentRetentionDesc": "Foto ed eventi sono conservati per la durata prevista dal piano: 90 giorni per Free, 12 mesi per Pro Event, 24 mesi per Wedding Pro e finché l’abbonamento è attivo per Professional (più 90 giorni di grazia dopo la cancellazione). L’add-on SnapRooms Vault può estendere la conservazione se attivo. Puoi scaricare i tuoi dati in qualsiasi momento prima della scadenza. Non promettiamo archiviazione illimitata o permanente.",
      "intellectualProperty": "Proprietà Intellettuale",
      "ipDesc1": "Il nome SnapRooms, il logo, il software, il design e tutti i diritti di proprietà intellettuale correlati ci appartengono e sono protetti dalle leggi applicabili su copyright, marchi e altro. Non puoi copiare, modificare, distribuire o creare opere derivate dalla nostra proprietà intellettuale senza il nostro previo consenso scritto.",
      "ipDesc2": "Il feedback che fornisci sul Servizio può essere utilizzato da noi senza restrizioni o compensazione.",
      "commercialUse": "Uso Commerciale & Licenza Privata",
      "commercialUseDesc1": "Uso personale e professionale. Puoi utilizzare SnapRooms sia per eventi personali (matrimoni, feste, riunioni) che come parte dei tuoi servizi professionali (fotografia di matrimoni, pianificazione eventi, gestione venue). Nessuna licenza commerciale aggiuntiva è richiesta per l'uso standard della piattaforma come previsto.",
      "commercialUseDesc2": "Cosa è permesso. Come abbonato Pro, puoi creare eventi illimitati per conto di clienti, condividere l'accesso agli eventi con clienti e ospiti, scaricare e consegnare raccolte di foto, e includere SnapRooms come parte dei tuoi pacchetti di servizi a pagamento.",
      "commercialUseDesc3": "Cosa non è permesso senza accordo scritto. Non puoi white-label o rivendere la piattaforma SnapRooms stessa, creare un servizio concorrente utilizzando la nostra infrastruttura, fare scraping o raccogliere sistematicamente dati dal Servizio, o utilizzare i nostri marchi in modo che suggerisca approvazione o partnership senza permesso scritto.",
      "commercialUseDesc4": "Termini personalizzati. Agenzie, venue e aziende con requisiti unici (come white-labeling, accesso API o impegni di volume) possono richiedere un accordo commerciale separato. Contattaci a hello@snaprooms.app per discutere licenze personalizzate.",
      "subscriptionsPayments": "Abbonamenti & Pagamenti",
      "subscriptionsDesc1": "SnapRooms offre un piano gratuito e un abbonamento Pro a pagamento. Le funzionalità Pro vengono fatturate in anticipo su base ricorrente. Puoi annullare il tuo abbonamento in qualsiasi momento tramite la tua dashboard. La cancellazione entra in vigore alla fine del periodo di fatturazione corrente.",
      "subscriptionsDesc2": "Utilizziamo Stripe per l'elaborazione dei pagamenti. Non archiviamo i dettagli completi della tua carta di pagamento. Tutte le transazioni sono soggette ai termini e alle condizioni di Stripe.",
      "subscriptionsDesc3": "Ci riserviamo il diritto di modificare i prezzi con preavviso ragionevole. Gli abbonati esistenti saranno notificati prima che qualsiasi modifica del prezzo influisca sul loro abbonamento.",
      "termination": "Risoluzione",
      "terminationDesc1": "Puoi smettere di utilizzare il Servizio e cancellare il tuo account in qualsiasi momento. Ci riserviamo il diritto di sospendere o terminare il tuo accesso se violi questi termini, sei coinvolto in attività fraudolente, o crei rischi o esposizione legale per noi o per altri utenti.",
      "terminationDesc2": "Alla risoluzione, i tuoi eventi e le foto associate possono essere conservati per un periodo limitato per consentire il recupero dei dati, dopodiché possono essere cancellati permanentemente. Non siamo obbligati a conservare i tuoi contenuti oltre il necessario per scopi legali o operativi.",
      "limitationOfLiability": "Limitazione di Responsabilità",
      "liabilityDesc1": "Il Servizio è fornito \"così com'è\" e \"come disponibile\" senza garanzie di alcun tipo, esplicite o implicite, incluse ma non limitate a garanzie di commerciabilità, idoneità per uno scopo particolare o non violazione.",
      "liabilityDesc2": "Nella massima misura consentita dalla legge applicabile, non saremo responsabili per danni indiretti, incidentali, speciali, consequenziali o punitivi, inclusa perdita di profitti, dati o goodwill, derivanti da o in connessione con il tuo uso del Servizio.",
      "liabilityDesc3": "La nostra responsabilità totale per qualsiasi reclamo derivante da o relativo a questi termini o al Servizio non supererà l'importo che ci hai pagato nei dodici (12) mesi precedenti il reclamo, o cento dollari USA ($100) se non hai effettuato alcun pagamento.",
      "disputeResolution": "Risoluzione delle Controversie",
      "disputeDesc": "Questi termini sono regolati e interpretati in conformità con le leggi della giurisdizione in cui opera SnapRooms, senza riguardo ai principi di conflitto di leggi. Qualsiasi controversia derivante da questi termini sarà prima affrontata attraverso la negoziazione di buona fede. Se irrisolta, le controversie saranno sottoposte ad arbitrato vincolante o ai tribunali competenti di tale giurisdizione, come da noi determinato.",
