      "permittedDesc2": "L'uso commerciale è permesso sia sotto abbonamenti Free che Pro, soggetto alle limitazioni delineate in questi termini. Gli abbonati Pro ricevono funzionalità estese inclusi eventi illimitati, gallerie permanenti e download in blocco.",
      "privateVsCommercial": "Distinzione Privato vs Commerciale",
      "privateVsCommercialDesc1": "L'uso privato si riferisce a eventi personali e non commerciali in cui sei l'host e il principale beneficiario (es. il tuo matrimonio, compleanno familiare, festa personale).",
      "privateVsCommercialDesc2": "L'uso commerciale si riferisce a qualsiasi uso in cui SnapRooms è incorporato in un'offerta di servizi per cui tu o la tua organizzazione ricevete una compensazione, o in cui agisci per conto di un cliente pagante.",
