      "contentDesc2": "Nous ne revendiquons pas la propriété de vos contenus. Nous ne vendons pas vos photos et ne les utilisons pas à des fins publicitaires sans votre consentement explicite. Vous êtes responsable de vous assurer que vous avez le droit de partager tout contenu téléchargé dans vos événements.",
      "contentDesc3": "Nous nous réservons le droit de supprimer du contenu qui viole ces conditions ou que nous croyons raisonnablement illégal, sans préavis.",
