      "commercialUseDesc2": "Ce qui est permis. En tant qu'abonné Pro, vous pouvez créer des événements illimités pour le compte de clients, partager l'accès aux événements avec clients et invités, télécharger et livrer des collections de photos, et inclure SnapRooms dans vos forfaits de services payants.",
