      "acceptanceOfTerms": "Al acceder o utilizar SnapRooms (\"el Servicio\"), aceptas estar vinculado por estos Términos de Servicio. Si no aceptas estos términos, no puedes usar el Servicio. Estos términos se aplican a todos los visitantes, usuarios, anfitriones de eventos y otros que acceden o utilizan el Servicio.",
      "acceptanceDesc1": "By accessing or using SnapRooms (\"the Service\"), you agree to be bound by these Terms of Service. If you do not agree to these terms, you may not use the Service. These terms apply to all visitors, users, event hosts, and others who access or use the Service.",
      "acceptanceDesc2": "Podemos actualizar estos términos de vez en cuando. El uso continuado del Servicio después de los cambios constituye la aceptación de los términos revisados. Los cambios sustanciales se comunicarán por correo electrónico o mediante un aviso prominente en la plataforma.",
      "serviceDescription": "Descripción del Servicio",
      "serviceDesc1": "SnapRooms es una plataforma web que permite a los anfitriones de eventos crear eventos de fotos privados, generar códigos QR y enlaces compartibles, y recopilar fotos de los invitados. Los invitados pueden subir fotos sin crear una cuenta. El Servicio incluye herramientas para moderación de fotos, gestión de galerías y descarga masiva.",
      "serviceDesc2": "No garantizamos acceso ininterrumpido al Servicio. El mantenimiento, las actualizaciones o circunstancias fuera de nuestro control pueden resultar en tiempo de inactividad temporal. Nos reservamos el derecho de modificar, suspender o discontinuar cualquier parte del Servicio en cualquier momento.",
