      "contentPhotos": "Contenido & Fotos",
      "contentDesc1": "Conservas la propiedad de todas las fotos y contenidos que tú o tus invitados suban a SnapRooms. Al subir contenido, nos otorgas una licencia limitada, no exclusiva y libre de regalías para almacenar, mostrar y transmitir ese contenido únicamente con el fin de operar el Servicio.",
      "contentDesc2": "No reclamamos la propiedad de tus contenidos. No vendemos tus fotos ni las usamos para publicidad sin tu consentimiento explícito. Eres responsable de asegurarte de tener el derecho de compartir cualquier contenido subido a tus eventos.",
      "contentDesc3": "Nos reservamos el derecho de eliminar contenido que viole estos términos o que razonablemente creemos ilegal, sin previo aviso.",
      "contentRetentionDesc": "Las fotos y eventos se almacenan durante la duración definida por tu plan: 90 días en Free, 12 meses en Pro Event, 24 meses en Wedding Pro, y mientras tu suscripción esté activa en Professional (más 90 días de gracia tras la cancelación). El add-on SnapRooms Vault puede extender el almacenamiento si está activo. Puedes descargar tus datos en cualquier momento antes de la expiración. No prometemos almacenamiento ilimitado o permanente.",
