      "serviceDescription": "Descrição do Serviço",
      "serviceDesc1": "O SnapRooms é uma plataforma baseada na web que permite que anfitriões de eventos criem eventos fotográficos privados, gerem códigos QR e links compartilháveis, e coletem fotos dos convidados. Os convidados podem enviar fotos sem criar uma conta. O Serviço inclui ferramentas para moderação de fotos, gerenciamento de galerias e download em lote.",
